/* Full preview · the Bixler's logo written by hand on the cover. Generated by
   assets/logo/trace-logo.py from the white logo (bixlers.com): the script is walked as pen
   strokes (B, ixler in one movement, then the x crossed, the i dotted, the apostrophe, s, mark),
   and logo-time.png holds, for every pixel of the logo, the moment the pen passes it; a filter
   reveals the pixels whose moment has come. The rules and 1785 open from the centre after. */
(() => {
  const el = document.querySelector('[data-logo-write]');
  if (!el) return;
  el.innerHTML = "<svg class=\"logo-write\" viewBox=\"0 0 1310 683\" aria-label=\"Bixler's 1785\" role=\"img\"><defs><filter id=\"lw-thr\" filterUnits=\"userSpaceOnUse\" x=\"0\" y=\"0\" width=\"1310\" height=\"683\" color-interpolation-filters=\"sRGB\"><feComponentTransfer><feFuncA id=\"lw-a\" type=\"linear\" slope=\"120\" intercept=\"0\"/></feComponentTransfer></filter><mask id=\"lw-mask\" maskUnits=\"userSpaceOnUse\" x=\"0\" y=\"0\" width=\"1310\" height=\"683\"><image href=\"logo-time.png?v=d8e9f668\" x=\"0\" y=\"0\" width=\"1310\" height=\"683\" filter=\"url(#lw-thr)\"/></mask></defs><image href=\"https://www.bixlers.com/cdn/shop/files/BX_REGIST_LOGO-1785_2025_1.png?v=1755892441&amp;width=1400\" x=\"0\" y=\"0\" width=\"1310\" height=\"683\" mask=\"url(#lw-mask)\"/></svg>";
  const fn = el.querySelector('#lw-a');
  // data-delay (s) holds the pen back, e.g. while the page before it fades away
  const SLOPE = 120, TOTAL = 3.658, START = 0.45 + (+el.dataset.delay || 0);
  let raf = 0;
  const write = () => {
    cancelAnimationFrame(raf);
    fn.setAttribute('intercept', -SLOPE);
    const t0 = performance.now();
    const tick = (now) => {
      const p = Math.max(0, (now - t0) / 1000 - START) / TOTAL;
      // at the end the mask opens fully: the finished logo is exactly the artwork
      fn.setAttribute('intercept', p < 1 ? (SLOPE * (p - 1)).toFixed(3) : 1);
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
  };
  // write whenever the cover comes into view
  const cover = el.closest('.slide');
  document.addEventListener('deck:slide', (e) => {
    if (e.detail.slide === cover) write();
  });
})();
